125	async function dispatchMeetingNoteRun({ service, actor }: { service: any; actor: any }) {
126	  await service.bootstrapMeetingWorkflowPack({ org_id: 'sample-project', project_id: 'sample-project' }, actor);
127	  const ingest = await service.ingestMeetingReviewPackage({ review_package: sampleMeetingReviewPackage() }, actor);
128	  const ingestRunId = ingest.meeting_review_ingest.run.id;
129	  const loopIntentId = meetingPackIds({
130	    orgId: 'sample-project',
131	    projectId: 'sample-project',
132	    definitionId: 'transcript-to-meeting-note'
133	  }).loopIntentId;
134	  const dispatched = await service.dispatchLoopIntentToEve(loopIntentId, {
135	    meeting_note_generation: { run_id: ingestRunId }
136	  }, actor);
137	  return { ingestRunId, dispatchRunId: dispatched.eve_session_dispatch.run.id };
138	}
