20	/**
21	 * Extracts every `record_meeting_note_generation` tool-call request from an
22	 * Eve session event stream. The tool-call input carries the generated note
23	 * (org/project/run refs, source_text_hash, note.title/body) even when the
24	 * Eve-side tool execution failed, so this is the pull-side source of truth.
25	 */
26	export function extractMeetingNoteToolCalls(events) {
27	    const calls = [];
28	    for (const event of Array.isArray(events) ? events : []) {
29	        if (event?.type !== 'actions.requested') continue;
30	        const actions = Array.isArray(event.data?.actions) ? event.data.actions : [];
31	        for (const action of actions) {
32	            if (action?.kind !== 'tool-call' || action.toolName !== MEETING_NOTE_TOOL_NAME) continue;
33	            if (!action.input || typeof action.input !== 'object') continue;
34	            calls.push({ call_id: action.callId || null, input: action.input });
35	        }
36	    }
37	    return calls;
38	}
