68	/**
69	 * Pull-based reconciler closing the Eve meeting-note loop.
70	 *
71	 * Eve (Vercel) cannot POST back to this Mac-local Brainbase instance, so the
72	 * dispatch run stays `running`/`await_eve_result` after the agent generates
73	 * the note. This worker polls the Eve session stream for each pending
74	 * dispatch run, extracts the generated note from the
75	 * `record_meeting_note_generation` tool-call input, verifies it against the
76	 * `run.metadata.meeting_note_generation` handoff (run_id + source_text_hash),
77	 * and records it through the local note-generation contract
78	 * (`workflowService.recordMeetingNoteGeneration`).
79	 */
80	export class EveMeetingNoteReconciler {
81	    constructor({
82	        workflowService,
83	        eveSessionClient,
84	        repository = null,
85	        config = {},
86	        clock = nowIso,
87	        logger = console
88	    }) {
89	        if (!workflowService) throw new Error('workflowService is required');
90	        this.workflowService = workflowService;
91	        this.eveSessionClient = eveSessionClient || workflowService.eveSessionClient || null;
92	        this.repository = repository || workflowService.repository;
93	        this.clock = clock;
94	        this.logger = logger;
95	        this.config = {
96	            enabled: config.enabled !== false,
97	            interval_ms: parseDurationMs(config.interval_ms ?? config.intervalMs, DEFAULT_INTERVAL_MS),
98	            immediate: config.immediate === true
99	        };
100	        this._scheduleTimer = null;
101	        this._runPromise = null;
102	    }
103	
104	    isConfigured() {
105	        return Boolean(this.eveSessionClient?.isConfigured?.());
106	    }
107	
108	    listPendingDispatchRuns() {
109	        this.repository.reload?.();
110	        return this.repository.listRuns({ limit: null })
111	            .filter((run) => run.env === 'eve')
112	            .filter((run) => run.status === 'running')
113	            .filter((run) => run.metadata?.meeting_note_generation?.run_id)
114	            .filter((run) => run.metadata?.runner?.session_id);
115	    }
116	
117	    async runOnce() {
118	        if (this._runPromise) return this._runPromise;
119	        this._runPromise = (async () => {
120	            const summary = {
121	                ran_at: this.clock(),
122	                configured: this.isConfigured(),
123	                checked: 0,
124	                recorded: 0,
125	                already_recorded: 0,
126	                blocked: 0,
127	                pending: 0,
128	                errors: []
129	            };
130	            if (!summary.configured) return summary;
131	            const runs = this.listPendingDispatchRuns();
132	            for (const run of runs) {
133	                summary.checked += 1;
134	                try {
135	                    const outcome = await this.reconcileRun(run);
136	                    if (outcome.status === 'recorded') summary.recorded += 1;
137	                    else if (outcome.status === 'already_recorded') summary.already_recorded += 1;
138	                    else if (outcome.status === 'blocked') summary.blocked += 1;
139	                    else summary.pending += 1;
140	                } catch (error) {
141	                    summary.errors.push({
142	                        run_id: run.id,
143	                        error: error?.message || String(error)
144	                    });
145	                    this.logger.warn?.(`[eve-note-reconciler] run ${run.id} failed: ${error?.message || error}`);
146	                }
147	            }
148	            return summary;
149	        })();
150	        try {
151	            return await this._runPromise;
152	        } finally {
153	            this._runPromise = null;
154	        }
155	    }
156	
157	    async reconcileRun(dispatchRun) {
158	        const meetingNoteGeneration = dispatchRun.metadata?.meeting_note_generation || {};
159	        const sessionId = dispatchRun.metadata?.runner?.session_id;
160	        const ingestRunId = meetingNoteGeneration.run_id;
161	
162	        if (this._targetAlreadyGenerated(ingestRunId)) {
163	            this._closeDispatchRun(dispatchRun, {
164	                status: 'success',
165	                reason: 'already_recorded',
166	                message: 'Meeting note was already recorded on the ingest run; closing the Eve dispatch run'
167	            });
168	            return { status: 'already_recorded', run_id: dispatchRun.id };
169	        }
170	
171	        const events = await this.eveSessionClient.readSessionStream({ sessionId });
172	        const noteCalls = extractMeetingNoteToolCalls(events);
173	        const matching = noteCalls.filter((call) => (
174	            call.input.source_text_hash === meetingNoteGeneration.source_text_hash
175	            && (!call.input.run_id || call.input.run_id === ingestRunId)
176	            && typeof call.input.note?.body === 'string'
177	            && call.input.note.body.trim() !== ''
178	        ));
179	        const noteCall = matching.at(-1) || null;
180	
181	        if (noteCall) {
182	            await this.workflowService.recordMeetingNoteGeneration({
183	                org_id: dispatchRun.org_id,
184	                project_id: dispatchRun.project_id,
185	                run_id: ingestRunId,
186	                source_text_hash: meetingNoteGeneration.source_text_hash,
187	                note: {
188	                    ...(typeof noteCall.input.note.title === 'string' ? { title: noteCall.input.note.title } : {}),
189	                    body: noteCall.input.note.body
190	                },
191	                runner: { type: 'eve', session_id: sessionId }
192	            }, { ...RECONCILER_ACTOR });
193	            this._closeDispatchRun(dispatchRun, {
194	                status: 'success',
195	                reason: 'note_reconciled',
196	                message: 'Eve session meeting note reconciled into the meeting_note_draft output',
197	                note_call_id: noteCall.call_id
198	            });
199	            return { status: 'recorded', run_id: dispatchRun.id, note_call_id: noteCall.call_id };
200	        }
201	
202	        const phase = classifySessionStreamPhase(events);
203	        if (phase === 'in_progress') {
204	            return { status: 'pending', run_id: dispatchRun.id, phase };
205	        }
206	
207	        // The session reached a boundary (parked / completed / failed) without a
208	        // usable note tool-call: no further output will arrive without operator
209	        // input, so surface the run instead of polling it forever.
210	        this._blockDispatchRun(dispatchRun, {
211	            phase,
212	            mismatched_note_calls: noteCalls.length - matching.length
213	        });
214	        return { status: 'blocked', run_id: dispatchRun.id, phase };
215	    }
216	
217	    _targetAlreadyGenerated(ingestRunId) {
218	        if (!ingestRunId) return false;
219	        const output = this.repository.listOutputs(ingestRunId)
220	            .find((candidate) => candidate.metadata?.output_key === 'meeting_note_draft');
221	        return output?.payload?.generation_status === 'brainbase_generated';
222	    }
223	
224	    _closeDispatchRun(dispatchRun, { status, reason, message, note_call_id = null }) {
225	        const finishedAt = this.clock();
226	        this.repository.updateRun(dispatchRun.id, {
227	            status,
228	            closure_state: 'closed',
229	            human_waiting: false,
230	            action_required: 'none',
231	            message,
232	            finished_at: finishedAt,
233	            metadata: {
234	                ...(dispatchRun.metadata || {}),
235	                eve_note_reconciler: {
236	                    reconciled_at: finishedAt,
237	                    reason,
238	                    ...(note_call_id ? { note_call_id } : {})
239	                }
240	            }
241	        });
242	        this._writeReconcilerAudit(dispatchRun, 'workflow.meeting_pack.note_generation.reconciled', {
243	            reason,
244	            note_call_id,
245	            ingest_run_id: dispatchRun.metadata?.meeting_note_generation?.run_id || null
246	        });
247	    }
248	
249	    _blockDispatchRun(dispatchRun, { phase, mismatched_note_calls = 0 }) {
250	        const finishedAt = this.clock();
251	        this.repository.updateRun(dispatchRun.id, {
252	            status: 'blocked',
253	            closure_state: 'closed',
254	            human_waiting: false,
255	            action_required: 'operator_review_eve_session',
256	            message: `Eve session ended (${phase}) without a matching record_meeting_note_generation call`,
257	            finished_at: finishedAt,
258	            metadata: {
259	                ...(dispatchRun.metadata || {}),
260	                eve_note_reconciler: {
261	                    reconciled_at: finishedAt,
262	                    reason: 'session_ended_without_note',
263	                    session_phase: phase,
264	                    mismatched_note_calls
265	                }
266	            }
267	        });
268	        this._writeReconcilerAudit(dispatchRun, 'workflow.meeting_pack.note_generation.reconcile_blocked', {
269	            reason: 'session_ended_without_note',
270	            session_phase: phase,
271	            mismatched_note_calls,
272	            ingest_run_id: dispatchRun.metadata?.meeting_note_generation?.run_id || null
273	        });
274	    }
275	
276	    _writeReconcilerAudit(dispatchRun, action, after) {
277	        this.repository.writeAuditLog({
278	            workspace_id: dispatchRun.workspace_id,
279	            org_id: dispatchRun.org_id || null,
280	            project_id: dispatchRun.project_id,
281	            actor_id: RECONCILER_ACTOR.sub,
282	            action,
283	            target_type: 'workflow_run',
284	            target_id: dispatchRun.id,
285	            after: {
286	                eve_session_id: dispatchRun.metadata?.runner?.session_id || null,
287	                ...after
288	            }
289	        });
290	    }
291	
292	    startScheduledReconcile(options = {}) {
293	        const config = {
294	            ...this.config,
295	            ...options,
296	            interval_ms: parseDurationMs(options.interval_ms ?? options.intervalMs, this.config.interval_ms)
297	        };
298	        if (!config.enabled) return { started: false, reason: 'disabled' };
299	        if (!this.isConfigured()) return { started: false, reason: 'eve_not_configured' };
300	        if (this._scheduleTimer) return { started: false, reason: 'already_started' };
301	        this.config = config;
302	        this._scheduleTimer = setInterval(() => {
303	            void this.runOnce().catch(() => {});
304	        }, config.interval_ms);
305	        this._scheduleTimer.unref?.();
306	        if (config.immediate) {
307	            void this.runOnce().catch(() => {});
308	        }
309	        return { started: true, interval_ms: config.interval_ms };
310	    }
311	
312	    stopScheduledReconcile() {
313	        if (!this._scheduleTimer) return { stopped: false, reason: 'not_started' };
314	        clearInterval(this._scheduleTimer);
315	        this._scheduleTimer = null;
316	        return { stopped: true };
317	    }
318	}
319	
320	export function createEveMeetingNoteReconcilerConfigFromEnv(env = process.env) {
321	    return {
322	        enabled: env.BRAINBASE_EVE_NOTE_RECONCILER_ENABLED !== '0',
323	        interval_ms: env.BRAINBASE_EVE_NOTE_RECONCILER_INTERVAL_MS,
324	        immediate: env.BRAINBASE_EVE_NOTE_RECONCILER_IMMEDIATE === '1'
325	    };
326	}
